      "line": 235,
      "column": 1614,
      "kind": "LastTemplateToken",
      "text": "</div><p class=\"sub\">دکمه‌ها کلمهٔ کامل را می‌خوانند؛ صدای آغاز حروف را با معلم یا ویدیوی فونیکس تمرین کن.</p><h2 class=\"sec\">۵ · بخوان و بساز</h2><div class=\"plan\"><h3>شیر کاغذی من 🦁</h3><p>در Student Book شیر کاغذی و در Workbook گربهٔ کاغذی می‌سازیم.</p><p class=\"reading en\">Color the body. Cut out the face. Fold the legs. Glue the paws on the legs.</p><p>رنگ کن ← ببر ← تا کن ← بچسبان</p><div class=\"row\"><button onclick=\"craft3()\">راهنمای ساخت</button><button onclick=\"start('read')\">تمرین دستورها</button></div></div><h2 class=\"sec\">۶ · گوش کن، صحبت کن، بنویس</h2><div class=\"lesson-note\">حیوان کاغذی‌ات را توصیف کن: <span class=\"en\">It is yellow. It has two ears. What is it?</span><br>دوستت حدس بزند: <span class=\"en\">It is a lion.</span></div><div class=\"row\"><button onclick=\"start('listen')\">تمرین شنیداری</button><button onclick=\"writing3()\">دربارهٔ بدن من</button><button onclick=\"start('count')\">شمارش جمله‌ها</button></div><p class=\"sub\">نقطه و علامت تعجب می‌توانند پایان جمله باشند. تعداد جمله‌ها با تعداد کلمه‌ها فرق دارد.</p><div class=\"row\"><button onclick=\"go('videos')\">موضوع‌های ویدیو</button><button class=\"cta\" style=\"font-size:20px\" onclick=\"go('practice')\">شروع تمرین‌ها</button></div>"
