      "text": "</div><label for=\"course-writing\">جمله‌های من</label><textarea id=\"course-writing\" class=\"course-notebook en\" maxlength=\"2000\" placeholder=\"Write your sentences here...\"></textarea><div class=\"row\"><button id=\"course-writing-save\">ذخیرهٔ نوشته</button><button id=\"course-writing-read\">🔊 نوشته‌ام را بخوان</button></div><p id=\"course-writing-status\" role=\"status\"></p><details class=\"plan\"><summary>جملهٔ نمونه</summary><p class=\"reading en\">"
