      "text": "</div><p>۱. الگو را گوش کن. ۲. با واژه‌های همین یونیت جملهٔ تازه بگو. ۳. نقش‌ها را عوض کنید.</p><p class=\"sub\">این تمرین دونفره است؛ صدا ضبط یا نمره‌گذاری نمی‌شود.</p>"
