          "title": "Fluency Time! 2 · معرفی افراد",
          "text": "This is my dad. / Nice to meet you. / Nice to meet you, too.",
          "fa": "کسی را معرفی کن و به معرفی دوستت پاسخ بده.",
          "project": "عروسک انگشتی: روی کاغذ شخصیت بکش و رنگ کن. با کمک بزرگ‌تر دورش را ببر، تا کن و کناره را بچسبان. برای عروسکت نام بگذار و با آن دوستت را معرفی کن.",
